{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C49"],
      "claim": "SRT2104, a high-transfer analogue, had absolute oral bioavailability of 13.8% (range 2–27%) in a Phase 1 human fasted-state study, below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C14"],
      "claim": "Revefenacin, a high-transfer analogue, showed absolute oral bioavailability <3% in healthy volunteers and COPD patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Enalkiren, a peptidomimetic renin inhibitor analogue, had human oral bioavailability of 0.5% at a 40 mg oral dose.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "GHRP-6, a peptide analogue, had systemic oral availability of approximately 0.3% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Lopinavir, a peptidomimetic HIV protease inhibitor analogue, has low oral bioavailability due to poor solubility/permeability and extensive CYP3A4/P-gp metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C30"],
      "claim": "Alvimopan had human oral bioavailability of 6%, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C42"],
      "claim": "Cromolyn oral solution had systemic bioavailability of approximately 1% in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Cyclandelate showed extremely low oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Octreotide oral formulation had 0.5% oral bioavailability in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Remikiren had absolute oral bioavailability of 0.3% in healthy male volunteers.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer experimental analogues show human oral bioavailability well below 20%, many below 5%, and the query shares peptidomimetic features with these poorly absorbed compounds. The fed-state condition may alter absorption but is unlikely to overcome the consistent low bioavailability supported by the evidence and the unfavorable physicochemical prior.",
  "evidence_gaps": [
    "No direct experimental bioavailability data for the query molecule itself.",
    "Most analogue data are from fasted or unspecified conditions; the query is assessed under fed state, and food effects are not directly captured.",
    "The query's formulation and dose are unknown, and bioavailability can be formulation-dependent.",
    "No direct data on whether the query is a substrate for efflux transporters or CYP metabolism, though analogues suggest such liabilities."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

